import { createHash } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { readFile, stat, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { inputs, repository, requireDraft, run } from './shared.mjs';

const { sourceCommit, releaseTag } = inputs();
if (process.platform !== 'darwin' || process.arch !== 'arm64') throw new Error('Publish only the native Apple silicon verification result.');
await requireDraft(releaseTag);
const source = process.env.ARYA_SOURCE_DIR, version = process.env.ARYA_RELEASE_VERSION;
if (`v${version}` !== releaseTag || await run('git', ['rev-parse', 'HEAD'], { cwd: source }) !== sourceCommit || await run('git', ['status', '--porcelain'], { cwd: source })) throw new Error('The current source differs from the authenticated release input.');
const output = join(source, '.build/releases', version);
const evidencePath = join(output, 'release.json');
const evidence = JSON.parse(await readFile(evidencePath, 'utf8'));
const filename = `AryaCode-${version}-macOS-arm64.dmg`;
if (evidence.version !== version || evidence.sourceCommit !== sourceCommit || evidence.artifact !== filename || evidence.architecture !== 'arm64' || evidence.portableDistribution !== true || evidence.externalLinks !== 0 || evidence.strictBundleVerification !== true || evidence.mountedImageSignatureVerification !== true || !['ad-hoc', 'Developer ID'].includes(evidence.signing) || typeof evidence.notarized !== 'boolean' || !/^[a-f0-9]{64}$/.test(evidence.sha256)) throw new Error('macOS release evidence does not match the requested source and signature verification.');
const hash = createHash('sha256');
for await (const chunk of createReadStream(join(output, filename))) hash.update(chunk);
if (hash.digest('hex') !== evidence.sha256) throw new Error('macOS package checksum verification failed.');
const checksums = await readFile(join(output, 'SHA256SUMS.txt'), 'utf8');
if (!checksums.split(/\r?\n/).includes(`${evidence.sha256}  ${filename}`)) throw new Error('macOS checksum manifest does not match the verified disk image.');
const inventoryName = `AryaCode-${version}-dependency-inventory.json`;
const inventory = JSON.parse(await readFile(join(output, inventoryName), 'utf8'));
if (inventory.version !== version || inventory.architecture !== 'arm64' || !Array.isArray(inventory.packages) || !inventory.packages.length) throw new Error('macOS dependency inventory is incomplete.');
const summaries = JSON.parse(await readFile(join(process.env.ARYA_BUILD_LOG_DIR, 'summary.json'), 'utf8'));
for (const phase of ['install', 'check', 'tools', 'editor-source', 'editor-setup', 'editor-compile', 'server-tools', 'application', 'native-extension', 'servers-extension', 'motion-extension', 'package']) if (!summaries.some(item => item.phase === phase && item.exitCode === 0)) throw new Error('A required macOS build or acceptance phase has not passed.');
const native = JSON.parse(await readFile(join(source, '.build/evidence/arya-native-workbench.json'), 'utf8'));
const servers = JSON.parse(await readFile(join(source, '.build/evidence/local-server-workbench.json'), 'utf8'));
const motion = JSON.parse(await readFile(join(source, '.build/evidence/motion-workbench.json'), 'utf8'));
if (native.passed !== true || servers.status !== 'passed' || servers.platform !== 'darwin' || motion.status !== 'passed' || motion.version !== version) throw new Error('Native language, server and motion extension-host acceptance evidence is incomplete.');
await writeFile(evidencePath, JSON.stringify({ ...evidence, bytes: (await stat(join(output, filename))).size, platformAcceptance: { runner: 'macos-15', architecture: 'arm64', nativeExtensionHost: true, liveServerExtensionHost: true, motionExtensionHost: true, runId: process.env.GITHUB_RUN_ID } }, null, 2) + '\n');
await requireDraft(releaseTag);
await run('gh', ['release', 'upload', releaseTag, '--repo', repository, '--clobber', ...[filename, 'SHA256SUMS.txt', 'release.json', inventoryName].map(file => join(output, file))], { timeoutMs: 1_800_000, failureMessage: 'Verified macOS release upload failed.' });
console.log(`Uploaded verified macOS arm64 package for ${sourceCommit} to draft ${releaseTag}. The release remains a draft.`);
